public List<Node> siblingNodes() {
    Node parent = parent();
    if (parent == null) {
        return Collections.emptyList();
    }

    List<Node> siblings = parent.childNodes();
    int index = siblings.indexOf(this);
    if (index >= 0) {
        return siblings.subList(0, index);
    }

    return Collections.emptyList();
}

